<script setup lang="ts">
import ServerSetup from '@/components/ServerSetup.vue';
import ServerAccount from '@/components/ServerAccount.vue';
import type {SetupStatus} from '@/services/api';
import {ref,computed,onMounted,onUnmounted,watch,nextTick} from 'vue';
import AppExperience from '@/components/AppExperience.vue';import ThemeEditor from '@/components/ThemeEditor.vue';import EditorChoice from '@/components/EditorChoice.vue';import PufferMark from '@/components/PufferMark.vue';
import CmsConnectionReport from '@/components/CmsConnectionReport.vue';import type {CmsStatus} from '@/services/api';
import {studioNavigation as allStudioNavigation} from '@/domain/studio-navigation';
const themeDesktop=import.meta.env.VITE_HETUN_THEME_DESKTOP==='1';
const operationsCenter=import.meta.env.VITE_HETUN_OPERATIONS_CENTER==='1';
const centerName=themeDesktop?'主题中心':operationsCenter?'运营中心':'影视中心';
const centerEnglish=themeDesktop?'HETUN THEME STUDIO':operationsCenter?'HETUN OPERATIONS CENTER':'HETUN CINEMA CENTER';
type StudioGroup={id:string;label:string;description:string;entries:readonly {id:string;icon:string;label:string;en:string}[]};
const studioNavigation:readonly StudioGroup[]=themeDesktop?[{id:'theme',label:'主题制作',description:'骨架、视觉与页面设计',entries:[...allStudioNavigation[0].entries,allStudioNavigation[1].entries[0]]},{id:'connection',label:'预览内容',description:'绑定真实内容用于设计',entries:[allStudioNavigation[1].entries.find(entry=>entry.id==='connection')!]}]:operationsCenter?[allStudioNavigation[1]]:allStudioNavigation;
const desktopBridge=()=> (window as any).hetunTheme;
async function desktopSettings(){await desktopBridge()?.settings();}
async function exportCurrent(){if(busy.value||locked.value)return;busy.value=true;error.value='';try{if(dirty.value)await saveDraft();const bundle=await api.exportTheme(selectedTemplate.value);const result=await desktopBridge()?.saveExport(bundle);if(result?.saved)message.value='主题包已导出，可添加到河豚打包器，与协议基础 APK 合并打包。';}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}

import {normalizeTheme} from '@/domain/normalize-theme';import defaults from '@/domain/default-theme.json';import {pageNames} from '@/domain/presentation';import type {Theme,Vod,Category,StudioState,Template,Platform,AppPage} from '@/domain/types';import {api,chooseLocalFile} from '@/services/api';
const centerMode=ref<'dark'|'light'>(uni.getStorageSync('hetun-center-appearance')==='light'?'light':'dark');function toggleCenterMode(){centerMode.value=centerMode.value==='dark'?'light':'dark';uni.setStorageSync('hetun-center-appearance',centerMode.value);}
const clone=<T,>(v:T):T=>JSON.parse(JSON.stringify(v));
const theme=ref<Theme>(clone(defaults) as Theme),published=ref<Theme>(clone(defaults) as Theme),templates=ref<Template[]>([]),selectedTemplate=ref(''),activeTemplates=ref<Partial<Record<Platform,string>>>({});
const authenticated=ref(false),checking=ref(true),username=ref('admin'),password=ref(''),loginError=ref(''),busy=ref(false),message=ref(''),error=ref(''),version=ref(0),publishedVersion=ref(0),savedSignature=ref(''),brandTab=ref(operationsCenter?'skeleton':'identity'),packageName=ref('');
const serverSetup=ref<SetupStatus|null>(null),releaseHistory=ref<{version:number;publishedAt:string}[]>([]);
async function rollback(){if(busy.value||locked.value)return;if(!releaseHistory.value.length){message.value='当前端暂无可回退的历史发布。';return;}uni.showActionSheet({itemList:releaseHistory.value.map(h=>'恢复发布 v'+h.version+' · '+h.publishedAt.slice(0,19)),success:r=>{const h=releaseHistory.value[r.tapIndex];uni.showModal({title:'回退运营配置',content:'将当前端草稿和发布内容恢复至 v'+h.version+'，未保存修改将丢失。客户端版本号继续递增。',success:async answer=>{if(!answer.confirm)return;busy.value=true;error.value='';try{cache.delete(selectedTemplate.value);receive(await api.rollback(version.value,h.version,selectedTemplate.value));scheduleContent();message.value='运营配置已恢复并重新发布。';}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}});}});}
const templateDialog=ref<'rename'|'remove'|''>(''),managedTemplate=ref<Template|null>(null),templateName=ref(''),allowUnpublish=ref(false),dialogError=ref('');
function setUnpublish(event:any){allowUnpublish.value=!!event.detail.value;}
const devices=[{id:'mobile',name:'手机',width:390,height:760},{id:'tablet',name:'平板',width:834,height:1112},{id:'tv',name:'电视',width:1280,height:720},{id:'web',name:'网页',width:1440,height:900}] as const;
const device=ref<Platform>('mobile'),stageWidth=ref(520),previewZoom=ref(1),viewportHeight=ref(900),viewportWidth=ref(1280),previewStage=ref<any>(null),startupPreview=ref(0),announcementPreview=ref(0),updatePreview=ref(0),previewPage=ref<AppPage>('home'),editing=ref(false),active=ref(operationsCenter?'layout':'brand'),selected=ref('hero'),publishedView=ref(false),cmsBase=ref(''),connectedBase=ref('');
const cmsStatus=ref<CmsStatus|null>(null),candidateStatus=ref<CmsStatus|null>(null),cmsChecking=ref(false),candidateChecking=ref(false);
let cmsEpoch=0,candidateEpoch=0,catalogEpoch=0,cmsPoll:ReturnType<typeof setInterval>|undefined,disposed=false;
const cmsLabel=computed(()=>!connectedBase.value?'等待连接苹果 CMS':cmsChecking.value?'正在检测苹果 CMS':!cmsStatus.value?'等待检测苹果 CMS':cmsStatus.value.status==='ready'?'苹果 CMS 已接通':cmsStatus.value.status==='empty'?'苹果 CMS 已接通 · 内容为空':'苹果 CMS 连接异常');
function clearContent(){catalogEpoch++;contentGeneration++;items.value=[];categories.value=[];sectionItems.value={};demo.value=false;}
watch(connectedBase,()=>{cmsEpoch++;cmsStatus.value=null;cmsChecking.value=false;clearContent();},{flush:'sync'});
watch(cmsBase,()=>{candidateEpoch++;candidateStatus.value=null;candidateChecking.value=false;},{flush:'sync'});
watch(authenticated,ready=>{if(!ready){cmsEpoch++;candidateEpoch++;cmsStatus.value=null;candidateStatus.value=null;cmsChecking.value=false;candidateChecking.value=false;clearContent();}},{flush:'sync'});
async function refreshCmsStatus(){
  if(disposed||!authenticated.value||cmsChecking.value)return;
  const gen=++cmsEpoch,base=connectedBase.value;cmsChecking.value=true;
  try{const report=await api.cmsStatus();if(disposed||gen!==cmsEpoch||base!==connectedBase.value||!authenticated.value)return;cmsStatus.value=report;if(report.ok)await loadContent();else{clearContent();previewError.value=report.configured?report.message:'';}}
  catch(e){if(disposed||gen!==cmsEpoch)return;cmsStatus.value={base,configured:!!base,ok:false,status:'error',checkedAt:new Date().toISOString(),latencyMs:0,checks:[],message:(e as Error).message};clearContent();previewError.value=(e as Error).message;}
  finally{if(gen===cmsEpoch)cmsChecking.value=false;}
}
async function checkCandidate(){
  if(busy.value||candidateChecking.value)return;
  const gen=++candidateEpoch;candidateChecking.value=true;error.value='';
  try{const report=await api.checkCms(cmsBase.value.trim());if(!disposed&&gen===candidateEpoch&&authenticated.value)candidateStatus.value=report;}
  catch(e){if(gen===candidateEpoch)error.value=(e as Error).message;}
  finally{if(gen===candidateEpoch)candidateChecking.value=false;}
}
const items=ref<Vod[]>([]),categories=ref<Category[]>([]),sectionItems=ref<Record<string,Vod[]>>({}),demo=ref(false),previewError=ref('');
const menu=studioNavigation.flatMap(g=>[...g.entries]);const expandedGroups=ref<Record<string,boolean>>({theme:true,templates:true,operations:true,connection:true});watch(active,id=>{const group=studioNavigation.find(g=>g.entries.some(e=>e.id===id));if(group)expandedGroups.value[group.id]=true;});
const currentMenu=computed(()=>menu.find(m=>m.id===active.value)!);const chosen=computed(()=>templates.value.find(t=>t.id===selectedTemplate.value));const platformTemplates=computed(()=>templates.value.filter(t=>t.platform===device.value));const locked=computed(()=>!chosen.value||chosen.value.platform!==device.value);const dirty=computed(()=>!locked.value&&JSON.stringify(theme.value)!==savedSignature.value);const unpublished=computed(()=>!chosen.value?.published||JSON.stringify(theme.value)!==JSON.stringify(published.value));const previewTheme=computed(()=>publishedView.value?published.value:theme.value);const previewDevice=computed(()=>devices.find(d=>d.id===device.value)!);const previewScale=computed(()=>Math.min(previewZoom.value,Math.max(160,stageWidth.value-24)/previewDevice.value.width));const canvasHeight=computed(()=>previewDevice.value.height);const screenSize=computed(()=>({width:previewDevice.value.width+'px',height:canvasHeight.value+'px',transform:'scale('+previewScale.value+')',background:previewTheme.value.colors.background}));const screenSpace=computed(()=>({width:previewDevice.value.width*previewScale.value+'px',height:canvasHeight.value*previewScale.value+'px'}));const pageOptions=computed(()=>Object.entries(pageNames).map(([id,label])=>({id,label})));
const lastTemplate:Partial<Record<Platform,string>>={};
const cache=new Map<string,{theme:Theme;version:number;signature:string}>();function retain(){if(selectedTemplate.value)cache.set(selectedTemplate.value,{theme:clone(theme.value),version:version.value,signature:savedSignature.value});}
function receive(s:StudioState,hydrate=true){releaseHistory.value=s.history||[];templates.value=s.templates;activeTemplates.value=s.activeTemplates;selectedTemplate.value=s.selectedTemplate;const currentTemplate=s.templates.find(t=>t.id===s.selectedTemplate);if(currentTemplate)lastTemplate[currentTemplate.platform]=s.selectedTemplate;version.value=s.version;publishedVersion.value=s.publishedVersion;published.value=normalizeTheme(clone(s.published));connectedBase.value=s.cmsBase;cmsBase.value=s.cmsBase;if(hydrate){const c=cache.get(s.selectedTemplate);if(c){theme.value=normalizeTheme(clone(c.theme));version.value=c.version;savedSignature.value=c.signature;}else{theme.value=normalizeTheme(clone(s.draft));savedSignature.value=JSON.stringify(theme.value);}}}
async function selectTemplate(id:string){if(busy.value)return;retain();busy.value=true;error.value='';try{receive(await api.state(id));device.value=chosen.value!.platform;previewPage.value='home';selected.value='hero';publishedView.value=false;scheduleContent();message.value='正在编辑：'+chosen.value!.name;}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function switchDevice(p:Platform){retain();device.value=p;publishedView.value=false;const t=templates.value.find(t=>t.platform===p&&t.id===(lastTemplate[p]||activeTemplates.value[p]))||templates.value.find(t=>t.platform===p);if(t)await selectTemplate(t.id);else{active.value='brand';brandTab.value='skeleton';}}
async function install(){if(!packageName.value.trim()){error.value='先为新骨架起名字。';return;}busy.value=true;error.value='';try{const file=await chooseLocalFile('.json,.zip');retain();const s=await api.install(packageName.value.trim(),file.data);receive(s);device.value=chosen.value!.platform;publishedView.value=false;previewPage.value='home';packageName.value='';scheduleContent();message.value='骨架已识别并安装，可独立编辑、保存和发布。';}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
function manageTemplate(t:Template,action:'rename'|'remove'){managedTemplate.value=t;templateName.value=t.name;allowUnpublish.value=false;dialogError.value='';templateDialog.value=action;}
async function commitTemplate(){const t=managedTemplate.value;if(!t||busy.value)return;busy.value=true;dialogError.value='';try{retain();const s=templateDialog.value==='rename'?await api.renameTemplate(t.id,templateName.value.trim(),t.version):await api.removeTemplate(t.id,t.version,allowUnpublish.value);if(templateDialog.value==='rename'){const c=cache.get(t.id);if(c)c.version=s.version;}else{cache.delete(t.id);delete lastTemplate[t.platform];}const renamed=templateDialog.value==='rename';receive(s);if(chosen.value)device.value=chosen.value.platform;templateDialog.value='';message.value=renamed?'骨架名称已更新。':'骨架库已更新。';scheduleContent();}catch(e){dialogError.value=(e as Error).message;}finally{busy.value=false;}}
let sectionRefresh:ReturnType<typeof setTimeout>|undefined,contentGeneration=0;
async function refreshSectionContent(){const gen=++contentGeneration;if(demo.value||!connectedBase.value||!cmsStatus.value?.ok){sectionItems.value={};return;}const result:Record<string,Vod[]>={};await Promise.all(previewTheme.value.sections.filter(s=>s.enabled&&((s.source==='category'&&s.categoryId)||(s.orderBy==='manual'&&s.manualIds)||s.orderBy==='score')).map(async s=>{try{result[s.id]=(await api.catalog(1,'',s.source==='category'?s.categoryId:'',s.orderBy==='manual'?s.manualIds||'':'',s.orderBy)).items;}catch(e){result[s.id]=[];if(!disposed&&gen===contentGeneration)previewError.value=(e as Error).message;}}));if(gen===contentGeneration)sectionItems.value=result;}
function scheduleContent(){if(sectionRefresh)clearTimeout(sectionRefresh);sectionRefresh=setTimeout(refreshSectionContent,350);}
async function loadContent(){const gen=++catalogEpoch;previewError.value='';if(!connectedBase.value){clearContent();return;}demo.value=false;try{const [c,t]=await Promise.all([api.catalog(),api.categories()]);if(disposed||gen!==catalogEpoch||!authenticated.value)return;items.value=c.items;categories.value=t.items;await refreshSectionContent();}catch(e){if(disposed||gen!==catalogEpoch)return;clearContent();previewError.value=(e as Error).message;if(cmsStatus.value)cmsStatus.value={...cmsStatus.value,ok:false,status:'error',message:'预览内容读取失败：'+(e as Error).message};}}
async function refreshSession(){try{serverSetup.value=await api.setup();authenticated.value=true;if(!serverSetup.value.installed)return;receive(await api.state());await refreshCmsStatus();}catch(e){if((e as any).status===401)authenticated.value=false;else error.value=(e as Error).message;}}
async function initialize(){try{await refreshSession();}finally{checking.value=false;}}
async function login(){busy.value=true;loginError.value='';try{await api.login(username.value,password.value);password.value='';authenticated.value=true;await refreshSession();}catch(e){loginError.value=(e as Error).message;}finally{busy.value=false;}}
async function saveDraft(){const snapshot=clone(theme.value);const s=await api.save(snapshot,version.value,selectedTemplate.value);cache.delete(selectedTemplate.value);receive(s,false);savedSignature.value=JSON.stringify(s.draft);if(JSON.stringify(theme.value)===JSON.stringify(snapshot))theme.value=clone(s.draft);retain();}
async function save(){if(busy.value||locked.value)return;busy.value=true;error.value='';try{await saveDraft();message.value='当前配置草稿已保存。';}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function publish(){if(busy.value||locked.value)return;busy.value=true;error.value='';try{if(dirty.value)await saveDraft();receive(await api.publish(version.value,selectedTemplate.value),false);message.value=themeDesktop?'当前骨架已发布到本机预览；导出后交给打包器。':operationsCenter?'运营配置已发布到'+previewDevice.value.name+'端；已接入运营协议的客户端将在下次同步时读取。':'当前骨架已发布到'+previewDevice.value.name+'端，在线客户端将在15秒内同步。';}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function performReload(){busy.value=true;try{cache.delete(selectedTemplate.value);receive(await api.state(selectedTemplate.value));await refreshCmsStatus();message.value='已读取当前骨架服务端草稿。';error.value='';}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
function reload(){if(dirty.value)uni.showModal({title:'重新加载',content:'将丢弃当前骨架未保存修改，是否继续？',success:r=>{if(r.confirm)performReload();}});else performReload();}
async function saveConnection(){if(busy.value||candidateChecking.value||cmsChecking.value)return;busy.value=true;error.value='';const base=cmsBase.value.trim();cmsEpoch++;cmsChecking.value=true;try{const s=await api.cms(base);connectedBase.value=s.cmsBase;cmsBase.value=s.cmsBase;cmsStatus.value=s.cmsStatus;if(s.cmsStatus.ok)await loadContent();else{clearContent();previewError.value='';}message.value=s.cmsBase?s.cmsStatus.message+' 已保存连接。':'CMS 连接已清除，客户端等待连接内容服务。';}catch(e){error.value=(e as Error).message;}finally{busy.value=false;cmsChecking.value=false;}}
async function logout(){await api.logout();authenticated.value=false;cache.clear();}
function selectSection(id:string){if(publishedView.value)return;selected.value=id;active.value=id==='brand'?(operationsCenter?'settings':'brand'):id==='ads'?'ads':(id==='navigation'||id==='categories')?'navigation':'layout';if(id==='brand'&&!operationsCenter)brandTab.value='identity';}
function openDemo(){if(locked.value)return;uni.navigateTo({url:device.value==='tv'?'/pages/tv/index':'/pages/demo/index?device='+device.value});}
function beforeLeave(e:BeforeUnloadEvent){if(dirty.value||[...cache.values()].some(c=>JSON.stringify(c.theme)!==c.signature)){e.preventDefault();e.returnValue='';}}
watch(()=>[previewTheme.value.sections,publishedView.value],scheduleContent,{deep:true});
// #ifdef H5
let previewObserver:ResizeObserver|undefined;watch([authenticated,checking],async ([ready,pending])=>{previewObserver?.disconnect();if(!ready||pending)return;await nextTick();const stage=previewStage.value instanceof HTMLElement?previewStage.value:previewStage.value?.$el;if(stage instanceof HTMLElement){previewObserver=new ResizeObserver(es=>{stageWidth.value=es[0].contentRect.width;});previewObserver.observe(stage);}});
// #endif
function measureViewport(){viewportHeight.value=window.innerHeight;viewportWidth.value=window.innerWidth;}
onMounted(()=>{if(themeDesktop||operationsCenter)uni.setNavigationBarTitle({title:'河豚'+centerName});initialize();cmsPoll=setInterval(()=>{if(authenticated.value&&connectedBase.value&&!busy.value)refreshCmsStatus();},60000);
// #ifdef H5
measureViewport();window.addEventListener('resize',measureViewport);window.addEventListener('beforeunload',beforeLeave);
// #endif
});onUnmounted(()=>{disposed=true;cmsEpoch++;candidateEpoch++;catalogEpoch++;contentGeneration++;if(cmsPoll)clearInterval(cmsPoll);if(sectionRefresh)clearTimeout(sectionRefresh);
// #ifdef H5
previewObserver?.disconnect();window.removeEventListener('resize',measureViewport);window.removeEventListener('beforeunload',beforeLeave);
// #endif
});
</script>
<template>
<view class="studio" :class="'center-'+centerMode">
  <view v-if="checking" class="loading-screen">正在连接河豚{{centerName}}…</view>
  <view v-else-if="!authenticated" class="login-screen"><view class="login-art"><view class="login-orbit o1"/><view class="login-orbit o2"/><view class="login-orbit o3"/><view class="login-copy"><view class="login-logo"><PufferMark :size="68" framed/><view class="login-wordmark"><text class="login-brand-name">河豚<text class="login-brand-center">{{centerName}}</text></text><text class="login-brand-en">{{centerEnglish}}</text></view></view><text class="login-eyebrow">{{centerEnglish}}</text><text class="login-title">每一种热爱，<br/>都有自己的模样。</text><text class="login-description">连接内容，编排故事。<br/>在这里，让你的放映室与众不同。</text></view><text class="login-bottom">A LITTLE CINEMA. ENDLESS POSSIBILITIES.</text></view><view class="login-form"><text class="form-eyebrow">YOUR CREATIVE SPACE</text><text class="form-title">欢迎回到河豚{{centerName}}</text><text class="form-description">{{operationsCenter?'登录以管理内容、栏目、广告与应用运营。':'登录以管理河豚 App 的主题与内容连接。'}}</text><view class="login-field"><text>管理员账号</text><input v-model="username" placeholder="管理员账号" @confirm="login"/></view><view class="login-field"><text>登录密码</text><input v-model="password" password :maxlength="-1" placeholder="输入管理员密码" @confirm="login"/></view><text v-if="loginError" class="form-error">{{loginError}}</text><button class="primary login-submit" :disabled="busy" @click="login">{{busy?'正在登录…':'进入河豚'+centerName}} <text>↗</text></button><text class="login-hint">管理员凭据由独立运行环境生成，保存在外部状态目录。</text></view></view>
  <ServerSetup v-else-if="operationsCenter&&serverSetup&&!serverSetup.installed" :status="serverSetup" @complete="refreshSession" @logout="logout"/>
  <template v-else>
  <view class="sidebar"><view class="studio-brand"><PufferMark :size="48" framed/><view class="brand-wordmark"><text class="studio-name">河豚<text class="studio-center">{{centerName}}</text></text><text class="studio-version">{{operationsCenter?'HETUN OPERATIONS':themeDesktop?'HETUN THEME':'HETUN CINEMA'}}</text></view></view><text class="nav-caption">{{operationsCenter?'应用运营工作台':'你的创作空间'}}</text><view class="side-menu"><view v-for="group in studioNavigation" :key="group.id" class="nav-group"><button class="nav-group-toggle" :aria-expanded="expandedGroups[group.id]" @click="expandedGroups[group.id]=!expandedGroups[group.id]"><view><text>{{group.label}}</text><text>{{group.description}}</text></view><text>{{expandedGroups[group.id]?'⌃':'⌄'}}</text></button><view v-show="expandedGroups[group.id]"><view v-for="entry in group.entries" :key="entry.id" class="menu-entry" :class="{active:active===entry.id}" @click="active=entry.id"><text class="menu-icon">{{entry.icon}}</text><view><text class="menu-label">{{entry.label}}</text><text class="menu-en">{{entry.en}}</text></view><text class="menu-arrow" v-if="active===entry.id">↗</text></view></view></view></view><view class="sidebar-foot"><view class="connection-status"><text class="status-dot" :class="{disconnected:!cmsStatus?.ok}"/><text>{{cmsLabel}}</text></view><text class="side-hint">{{themeDesktop?'制作、预览并导出主题包':'主题与内容，通过河豚服务'}}<br/>{{themeDesktop?'支持手机、平板、TV 和网页。':'同步至手机、平板、TV 和网页。'}}</text><view v-if="!themeDesktop" class="side-foot-links"><text @click="logout">退出</text></view></view></view>
  <view class="workspace">
<view class="workspace-header"><view><view class="breadcrumb">管理中心 <text>/</text> {{chosen?.name||'骨架管理'}}</view><text class="workspace-title">河豚{{centerName}} <text class="workspace-en">{{operationsCenter?'OPERATIONS CENTER':themeDesktop?'THEME STUDIO':'CINEMA CENTER'}}</text></text></view><view class="header-actions"><button v-if="themeDesktop" class="ghost" @click="desktopSettings">服务设置</button><button v-if="themeDesktop" class="ghost" :disabled="busy||locked" @click="exportCurrent">导出主题包</button><button v-if="operationsCenter" class="ghost" :disabled="busy||locked" @click="rollback">发布历史</button><button class="appearance-toggle" :aria-label="centerMode==='dark'?'切换日间模式':'切换夜间模式'" :title="centerMode==='dark'?'切换日间模式':'切换夜间模式'" @click="toggleCenterMode"><text>{{centerMode==='dark'?'☀':'☾'}}</text><text>{{centerMode==='dark'?'日间':'夜间'}}</text></button><text class="save-status">{{locked?'此端未安装骨架':dirty?'有未保存修改':'草稿已保存'}}</text><button class="ghost" :disabled="busy||locked" @click="save">保存草稿</button><button class="primary" :disabled="busy||locked||(!unpublished&&!dirty)" @click="publish">{{themeDesktop?'发布本机预览':'发布到'+previewDevice.name+'端'}} ↗</button></view></view>
<view class="context-strip"><text>{{operationsCenter?'当前运营配置：':'当前骨架：'}}{{locked?'未安装':chosen?.name}} · {{operationsCenter?'四端独立保存与发布，模板在打包器选择':'每套骨架独立编辑与发布'}}</text><text class="version-tag">LIVE v{{publishedVersion}}</text></view>
<view v-if="error||message" class="feedback" :class="{failure:!!error}"><text>{{error||message}}</text><text @click="error='';message=''">×</text></view>
<view class="design-grid"><view class="editor-column"><view class="editor-title"><view><text class="panel-eyebrow">CUSTOMIZE YOUR CINEMA</text><text class="panel-title">{{currentMenu.label}}</text></view><text class="editor-icon">{{currentMenu.icon}}</text></view>
<view v-if="active==='brand'&&!operationsCenter" class="brand-switch" role="tablist" aria-label="品牌与骨架编辑切换"><button role="tab" :aria-selected="brandTab==='identity'" :class="{chosen:brandTab==='identity'}" @click="brandTab='identity'">品牌标识</button><button role="tab" :aria-selected="brandTab==='skeleton'" :class="{chosen:brandTab==='skeleton'}" @click="brandTab='skeleton'">App 骨架</button></view>
<view class="editor-scroll"><view v-if="active==='brand'&&brandTab==='skeleton'" class="editor-card"><view class="card-heading">骨架库 · {{previewDevice.name}}端</view><text class="card-description">上传对应端的模板包，识别通过后安装。选择哪套，就编辑哪套。</text><view class="device-switch"><button v-for="d in devices" :key="d.id" :class="{chosen:device===d.id}" :disabled="busy" @click="switchDevice(d.id)">{{d.name}}</button></view><view v-for="t in platformTemplates" :key="t.id" class="template-row" :class="{chosen:selectedTemplate===t.id}" @click="selectTemplate(t.id)"><view><text>{{t.name}}</text><text class="card-description">{{t.id}} · 草稿 v{{t.version}} · {{t.published?'已发布':'待发布'}}</text></view><view class="template-actions" @click.stop><button :disabled="busy" @click="selectTemplate(t.id);if(operationsCenter){active='layout'}else{brandTab='identity'}">{{operationsCenter?'配置':'编辑'}}</button><button :disabled="busy" @click="manageTemplate(t,'rename')">改名</button><button class="danger" :disabled="busy" @click="manageTemplate(t,'remove')">删除</button><text>{{selectedTemplate===t.id?'✓ 当前骨架':'点击选择'}}</text></view></view><view v-if="!platformTemplates.length" class="locked-note">此端全部锁定，安装有效骨架后解锁。</view><view class="field"><text class="field-label">新骨架名称</text><input v-model="packageName" placeholder="为你的骨架起名字" maxlength="40"/></view><button class="primary" :disabled="busy" @click="install">{{busy?'处理中…':'上传 JSON / ZIP 并安装'}}</button><text class="card-description">模板包包含平台标识、页面结构、排版配置和素材。安装后保留原有骨架。</text></view>
<view v-else-if="active==='connection'" class="editor-card"><ServerAccount v-if="operationsCenter"/><view class="card-heading">连接苹果 CMS</view><text class="card-description">检测分类与影片接口，预览读取当前已保存站点的真实内容。</text><view class="field"><text class="field-label">CMS 站点地址</text><input v-model="cmsBase" placeholder="https://你的CMS站点" :disabled="busy"/></view><view class="cms-actions"><button :disabled="busy||candidateChecking||cmsChecking" @click="checkCandidate">{{candidateChecking?'检测中…':'检测地址'}}</button><button class="primary" :disabled="busy||candidateChecking||cmsChecking" @click="saveConnection">保存并检测连接</button><button :disabled="busy||cmsChecking||candidateChecking||!connectedBase" @click="refreshCmsStatus">重新检测当前连接</button></view><text class="card-description">检测地址不会保存配置。保存前必须通过分类和影片接口检查；已保存连接每 60 秒自动复检并刷新预览内容。</text><CmsConnectionReport :report="cmsStatus" title="当前使用的连接" :checking="cmsChecking"/><CmsConnectionReport v-if="candidateStatus||candidateChecking" :report="candidateStatus" title="待保存地址检测结果" :checking="candidateChecking"/><text class="card-description">会员登录、支付与播放权限需要另外联调验证，内容连接通过不代表这些功能已通过。</text></view>
<view v-else-if="locked" class="editor-card locked-note">{{previewDevice.name}}端未安装骨架。请在品牌与骨架 → App 骨架上传对应模板。</view>
<ThemeEditor v-else :theme="theme" :active="active" :selected="selected" :page="previewPage" :categories="categories" @select="selected=$event" @page="previewPage=$event" @message="message=$event" @startup="startupPreview++;editing=false" @announcement="announcementPreview++;editing=false" @update="updatePreview++;editing=false"/>
</view><view class="editor-footer"><text>{{locked?'未安装':'草稿 v'+version+' · '+theme.sections.filter(s=>s.enabled).length+' 个可见模块'}}</text><text @click="reload">重新加载 ↻</text></view></view>
<view class="preview-column"><view class="preview-toolbar"><view><view class="preview-heading"><text class="status-dot"/><text>实时预览</text><text class="preview-live">LIVE</text></view><text class="preview-caption">{{cmsLabel}}</text><text v-if="operationsCenter" class="preview-caption">运营预览使用内置参考外观，安装包实际外观由打包器选择的主题决定。</text></view><view class="device-switch" role="tablist" aria-label="四端预览切换"><button v-for="d in devices" :key="d.id" role="tab" :aria-selected="device===d.id" :class="{chosen:device===d.id}" :disabled="busy" @click="switchDevice(d.id)">{{d.name}}{{templates.some(t=>t.platform===d.id)?'':' 🔒'}}</button></view></view>
<view class="preview-subbar"><view class="preview-tabs"><text :class="{chosen:!publishedView}" @click="publishedView=false">草稿</text><text :class="{chosen:publishedView}" @click="chosen?.published&&(publishedView=true)">{{chosen?.published?'已发布':'尚未发布'}}</text></view><view class="preview-tabs"><text :class="{chosen:editing}" @click="editing=true">编辑</text><text :class="{chosen:!editing}" @click="editing=false">浏览</text></view><view class="preview-zoom"><button :disabled="previewZoom<=.75" @click="previewZoom=Math.max(.75,previewZoom-.25)">−</button><button @click="previewZoom=1">{{Math.round(previewScale*100)}}%</button><button :disabled="previewZoom>=1.5" @click="previewZoom=Math.min(1.5,previewZoom+.25)">＋</button></view><text class="preview-dimensions">{{previewDevice.width}} × {{canvasHeight}}</text></view>

<view ref="previewStage" class="preview-stage"><view v-if="locked" class="locked-preview"><PufferMark :size="72"/><text>{{previewDevice.name}}端待安装</text><text>上传此端骨架包后，预览将显示它自己的界面。</text><button class="ghost" @click="active='brand';brandTab='skeleton'">进入骨架库</button></view><view v-else class="preview-frame" :class="device" :style="{background:previewTheme.colors.background}"><view v-if="device==='mobile'" class="phone-status"><text>9:41</text><view class="island"/><text>▮▮▮ ▰</text></view><view class="screen-space" :style="screenSpace"><view class="preview-viewport" :style="screenSize"><AppExperience studio :template-key="selectedTemplate" :announcement-preview="announcementPreview" :update-preview="updatePreview" :key="selectedTemplate+'-'+publishedView" :theme="previewTheme" :items="items" :categories="categories" :section-items="sectionItems" :demo="demo" :error="previewError" :editing="editing&&!publishedView" :platform="device" :startup-preview="startupPreview" :selected="selected" :page="previewPage" @select="selectSection" @page="previewPage=$event" @retry="loadContent"/></view></view><view v-if="device==='mobile'" class="phone-home"><view/></view></view></view><view class="preview-footer"><view class="demo-actions"><text>{{previewDevice.name}}端客户端</text><button class="ghost" :disabled="locked||!activeTemplates[device]" @click="openDemo">打开已发布客户端 ↗</button></view><text class="demo-public-hint">编辑模式点模块调整；浏览模式点开详情、会员、分类和其他页面。</text></view></view>
</view></view><view v-if="templateDialog" class="modal-shade"><view class="template-dialog"><text class="dialog-title">{{templateDialog==='rename'?'修改骨架名称':'删除骨架'}}</text><text class="card-description">{{managedTemplate?.name}}</text><input v-if="templateDialog==='rename'" v-model="templateName" maxlength="40" placeholder="输入骨架名称"/><template v-else><text class="card-description">删除后，这套骨架的草稿和已发布版本会从骨架库移除。</text><view v-if="managedTemplate&&activeTemplates[managedTemplate.platform]===managedTemplate.id" class="delete-confirm"><switch :checked="allowUnpublish" @change="setUnpublish"/><text>停止此端当前发布，并删除骨架</text></view></template><text v-if="dialogError" class="form-error">{{dialogError}}</text><view class="dialog-actions"><button class="ghost" :disabled="busy" @click="templateDialog=''">取消</button><button class="primary" :disabled="busy||!!(templateDialog==='remove'&&managedTemplate&&activeTemplates[managedTemplate.platform]===managedTemplate.id&&!allowUnpublish)" @click="commitTemplate">{{templateDialog==='rename'?'保存名称':'确认删除'}}</button></view></view></view></template></view></template>
